  describe('integration with resume', () => {
    it('rejoins a conversation whose id came from a list', async () => {
      const sessionId = 's1';
      const userId = 'u1';
      const session: ChatSession = {
        sessionId,
        userId,
        entries: [{role: 'user', content: 'hi', timestamp: new Date().toISOString()}],
      };

      const store = {
        get: jest.fn().mockResolvedValue(session),
        listFor: jest.fn().mockResolvedValue([{sessionId, createdAt: new Date(), updatedAt: new Date(), entryCount: 1}]),
      } as any;

      // 1. Get the list
      const h = harness([]);
      const config = {transport: {history: {enabled: true}, resume: {enabled: true}}} as any;
      const handle = createMessageHandler(h.orchestrator, store, config);
      await handle(h.ws, h.session, {type: 'list_conversations'});

      const listFrame = h.sent[0] as any;
      const idFromList = listFrame.conversations[0].sessionId;

      // 2. Reconnect with that ID
      const {resumableSession} = await import('./sessionResume.js');
      const requester = {requestedSessionId: idFromList, userId};
      const outcome = await resumableSession(store, requester, config.transport.resume);

      expect(outcome.session).toBe(session);
      expect(outcome.session?.sessionId).toBe(sessionId);
    });

    it('ConnectedMessage is unchanged by this issue', async () => {
      const {ConnectedMessage} = await import('../../types/messages.js');
      // This is a type-level check primarily, but we can verify no new fields were added that shouldn't be there.
      const msg: any = {
        type: 'connected',
        sessionId: 's1',
        message: 'hi',
        examplePrompts: [],
      };
      // Should not have any history-related fields
      expect(msg.history).toBeUndefined();
      expect(msg.conversations).toBeUndefined();
    });
  });
});

